        if fg_color == bg:
            continue

        # Find all positions of this color
        pos_r = []
        pos_c = []
        for r in range(rows):
            for c in range(cols):
                if original[r][c] == fg_color:
                    pos_r.append(r)
                    pos_c.append(c)

        if len(pos_r) < 2:
            continue

        # Sort by row, get col positions per row
        cols_by_row = {}
        for i, (r, c) in enumerate(zip(pos_r, pos_c)):
            cols_by_row[r] = cols_by_row.get(r, []) + [c]

        for r in sorted(cols_by_row.keys()):
            cols_list = sorted(cols_by_row[r])
            for i in range(len(cols_list) - 1):
                c1, c2 = cols_list[i], cols_list[i+1]
                # Fill horizontal gap
                for k in range(c1 + 1, c2):
                    if original[r][k] == bg:
                        out[r][k] = 2

        # Sort by col, get row positions per col
        rows_by_col = {}
        for i, (r, c) in enumerate(zip(pos_r, pos_c)):
            rows_by_col[c] = rows_by_col.get(c, []) + [r]

